		DiagnosticBag candidateDiagnostics;if(!document){candidateDiagnostics.error("MPP-PIPELINE-RUNTIME-001","Pipeline document is missing.");mDiagnostics=candidateDiagnostics;return false;}candidateDiagnostics=document->validate(mRenderSystem->getCaps(),glm::uvec2(viewportWidth,viewportHeight));candidateDiagnostics.append(document->validateOutputAntiAliasing(mRenderSystem->getOptions().antiAliasing,&mRenderSystem->getCaps()));for(auto const& output:document->outputs){auto effective=resolveAntiAliasing(mRenderSystem->getOptions().antiAliasing,output.antiAliasing);auto width=(uint64_t)ssaaDimension(viewportWidth,effective.ssaa),height=(uint64_t)ssaaDimension(viewportHeight,effective.ssaa);if(width>(uint64_t)mRenderSystem->getCaps().maxTextureSize||height>(uint64_t)mRenderSystem->getCaps().maxTextureSize)candidateDiagnostics.error("MPP-PIPELINE-RUNTIME-009","Output '"+output.name+"' SSAA requires "+std::to_string(width)+"x"+std::to_string(height)+", exceeding the GPU maximum texture size.",{document->sourcePath},output.name);}candidateDiagnostics.append(validatePbrPipelineResourceDefinitions(*document));if(candidateDiagnostics.hasErrors()){mDiagnostics=candidateDiagnostics;return false;}auto suffix=std::to_string(++mGeneration),candidateRoot="PbrPipelineRuntime."+suffix;std::map<std::string,ResourcePtr> candidateBindings;std::map<std::string,UniformCollection> candidateOverrides;std::map<std::string,RenderTargetPtr> candidateImports;RenderTargetPtr candidatePresentation;PbrEnvironmentPtr candidateEnvironment=std::make_shared<PbrEnvironment>();bool rootDeclared=false;
