			for(auto const& overrideValue:document->previewOverrides){auto material=candidateBindings.find(overrideValue.binding);if(material==candidateBindings.end()){candidateDiagnostics.warning("MPP-PIPELINE-RUNTIME-004","Preview override for model '"+overrideValue.modelId+"' is inactive because its material binding is unresolved.",{document->sourcePath},overrideValue.modelId);continue;}static_cast<PbrMaterial*>(material->second.get())->validateInstanceUniforms(overrideValue.values);candidateOverrides[overrideValue.modelId]=overrideValue.values;}
			ResourcePtr hdrEquirectangularSource;std::filesystem::path hdrSourcePath;if(!document->environment.hdrEquirectangular.empty()){try{auto path=std::filesystem::path(document->environment.hdrEquirectangular);if(path.is_relative())path=std::filesystem::path(document->sourcePath).parent_path()/path;path=std::filesystem::absolute(path).lexically_normal();hdrSourcePath=path;auto stream=new ProgrammaticTextureStream(mResourceManager);stream->setTarget(TextureTarget::Texture2D);stream->setColourSpace(TextureColourSpace::Linear);stream->setFile(path.string(),mResourceManager->getImageLoadFunction());hdrEquirectangularSource=mResourceManager->declareResource(candidateRoot+"/HdrEquirectangular",ResourceStreamPtr(stream)).first;hdrEquirectangularSource->load();auto image=dynamic_cast<Texture*>(hdrEquirectangularSource.get());if(!image||image->getTextureTarget()!=GL_TEXTURE_2D||(image->getInternalFormat()!=GL_RGB16F&&image->getInternalFormat()!=GL_RGBA16F&&image->getInternalFormat()!=GL_RGB32F&&image->getInternalFormat()!=GL_RGBA32F))throw std::runtime_error("HDR IBL source '"+path.string()+"' must decode as a linear floating-point RGB/RGBA Texture2D.");}catch(std::exception const& error){candidateDiagnostics.warning("MPP-PIPELINE-RUNTIME-012",std::string("HDR IBL source could not be loaded; neutral IBL fallback remains active: ")+error.what(),{document->sourcePath},document->environment.binding);hdrEquirectangularSource.reset();}}
