			if(hdrEquirectangularSource){try{IblEnvironmentCacheKey key;key.source=hdrSourcePath;key.environmentResolution=document->environment.environmentResolution;key.irradianceResolution=document->environment.irradianceResolution;key.prefilterResolution=document->environment.prefilterResolution;auto generated=mRenderSystem->getIblEnvironmentCache().find(key);if(!generated){auto source=dynamic_cast<Texture*>(hdrEquirectangularSource.get());uint32_t environmentMipLevels=1;for(auto dimension=key.environmentResolution;dimension>1;dimension>>=1)++environmentMipLevels;auto environment=mRenderSystem->convertEquirectangularToCubemap(source,candidateRoot+".IblEnvironment",key.environmentResolution,environmentMipLevels);auto irradiance=mRenderSystem->generateDiffuseIrradiance(dynamic_cast<Texture*>(environment.get()),candidateRoot+".IblIrradiance",key.irradianceResolution);uint32_t mipLevels=1;for(auto dimension=key.prefilterResolution;dimension>1;dimension>>=1)++mipLevels;auto prefiltered=mRenderSystem->generatePrefilteredSpecular(dynamic_cast<Texture*>(environment.get()),candidateRoot+".IblPrefiltered",key.prefilterResolution,mipLevels);generated=std::make_shared<IblEnvironmentResources>();generated->environmentCubemap=std::static_pointer_cast<Resource>(std::dynamic_pointer_cast<RenderTexture>(environment));generated->irradianceCubemap=std::static_pointer_cast<Resource>(std::dynamic_pointer_cast<RenderTexture>(irradiance));generated->prefilteredSpecularCubemap=std::static_pointer_cast<Resource>(std::dynamic_pointer_cast<RenderTexture>(prefiltered));generated->brdfLut=mRenderSystem->getOrCreatePbrBrdfIntegrationLut();mRenderSystem->getIblEnvironmentCache().store(key,generated);}candidateEnvironment->environmentMap=generated->environmentCubemap;candidateEnvironment->irradianceMap=generated->irradianceCubemap;candidateEnvironment->prefilteredSpecularMap=generated->prefilteredSpecularCubemap;candidateEnvironment->brdfIntegrationLut=generated->brdfLut;}catch(std::exception const& error){candidateDiagnostics.warning("MPP-PIPELINE-RUNTIME-011",std::string("HDR IBL generation failed; neutral IBL fallback remains active: ")+error.what(),{document->sourcePath},document->environment.binding);candidateEnvironment->irradianceMap=texture("","__mpp_tex_pbr_ibl_cube__","irradiance");candidateEnvironment->prefilteredSpecularMap=texture("","__mpp_tex_pbr_ibl_cube__","prefiltered specular");candidateEnvironment->brdfIntegrationLut=mRenderSystem->getOrCreatePbrBrdfIntegrationLut();}}else{candidateEnvironment->irradianceMap=texture(document->environment.irradiance,"__mpp_tex_pbr_ibl_cube__","irradiance");candidateEnvironment->prefilteredSpecularMap=texture(document->environment.prefilteredSpecular,"__mpp_tex_pbr_ibl_cube__","prefiltered specular");if(document->environment.brdfLut.empty())candidateEnvironment->brdfIntegrationLut=mRenderSystem->getOrCreatePbrBrdfIntegrationLut();else candidateEnvironment->brdfIntegrationLut=texture(document->environment.brdfLut,"__mpp_tex_pbr_brdf_lut__","BRDF LUT");if(auto lut=dynamic_cast<Texture*>(candidateEnvironment->brdfIntegrationLut.get());!lut||lut->getTextureTarget()!=GL_TEXTURE_2D){candidateDiagnostics.warning("MPP-PIPELINE-RUNTIME-010","Environment BRDF LUT override is not a Texture2D; using renderer-generated LUT.",{document->sourcePath},document->environment.binding);candidateEnvironment->brdfIntegrationLut=mRenderSystem->getOrCreatePbrBrdfIntegrationLut();}}candidateEnvironment->backgroundMap=texture(document->environment.background,"__mpp_tex_pbr_ibl_cube__","background");if(!candidateEnvironment->environmentMap)candidateEnvironment->environmentMap=candidateEnvironment->backgroundMap;
